create table public.manager_auth_handoffs (code_hash text primary key, auth_user_id uuid not null references auth.users(id) on delete cascade, destination text not null check (destination = 'vote'), created_at timestamptz not null default now(), expires_at timestamptz not null default (now() + interval '2 minutes'), consumed_at timestamptz); alter table public.manager_auth_handoffs enable row level security; revoke all on public.manager_auth_handoffs from anon, authenticated;